declare(strict_types=1);namespace Atlas\Platform\Workflows\Authoring;use InvalidArgumentException;final class WorkflowDraftValidator{private const UUID='/^[a-f0-9]{8}-[a-f0-9]{4}-[1-5][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/i';public function normalize(array$input):array{$text=static fn(mixed$v,int$max):string=>substr(trim(is_string($v)?$v:''),0,$max);$scope=$text($input['scope']??'',20);if(!in_array($scope,['platform','organization'],true)){throw new InvalidArgumentException('Workflow scope must be platform or organization.');}$slug=strtolower($text($input['slug']??'',191));if(preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$slug)!==1){throw new InvalidArgumentException('Workflow slug is invalid.');}$title=$text($input['title']??'',255);if($title===''){throw new InvalidArgumentException('Workflow title is required.');}$source=$text($input['source_resource_version_id']??'',36);if($source!==''&&preg_match(self::UUID,$source)!==1){throw new InvalidArgumentException('Source resource version identifier is invalid.');}$steps=$input['steps']??null;if(!is_array($steps)||$steps===[]||count($steps)>50){throw new InvalidArgumentException('A workflow requires 1 to 50 ordered steps.');}$normalized=[];foreach(array_values($steps)as$position=>$step){if(!is_array($step)){throw new InvalidArgumentException('Every workflow step must be an object.');}$stepTitle=$text($step['title']??'',255);$instruction=$text($step['instruction']??'',5000);$requirement=$text($step['requirement']??'',5000);$related=$text($step['related_resource_id']??'',36);if($stepTitle===''||$instruction===''||$requirement===''){throw new InvalidArgumentException('Every workflow step requires title, instruction, and requirement.');}if($related!==''&&preg_match(self::UUID,$related)!==1){throw new InvalidArgumentException('Related resource identifier is invalid.');}$normalized[]=['position'=>$position+1,'title'=>$stepTitle,'instruction'=>$instruction,'requirement'=>$requirement,'warning'=>$text($step['warning']??'',5000),'related_resource_id'=>$related];}return['scope'=>$scope,'slug'=>$slug,'title'=>$title,'summary'=>$text($input['summary']??'',2000),'source_resource_version_id'=>$source,'steps'=>$normalized];}}
